+        LINEAR_MAPPING_BASE_VADDR
+    }
+
+    open spec fn vmalloc_base_vaddr_spec() -> Vaddr {
+        VMALLOC_BASE_VADDR
+    }
+
+    proof fn lemma_model_requirements() {
+        assert(Self::linear_mapping_base_vaddr_spec() % Self::C::BASE_PAGE_SIZE() == 0)
+            by (compute_only);
