    const HIGHEST_TRANSLATION_LEVEL: PagingLevel = 4;
    const PTE_SIZE: usize = core::mem::size_of::<PageTableEntry>();
}
```
Please also add such a comment in `x86` and remove those function-level comments like 
```
/* Share the base page size with const-generic layouts and the paging model.
         * Origin Rust: 4096
         */
```

